import 'package:hive/hive.dart';

// This is a necessary part for the generator
part 'transaction.g.dart';

@HiveType(typeId: 1)
class Transaction {
  @HiveField(0)
  final String name;

  @HiveField(1)
  final double amount;

  @HiveField(2)
  final bool isExpense;

  Transaction({
    required this.name,
    required this.amount,
    required this.isExpense,
  });
}

