final transactionsBox = Hive.box<Transaction>('transactions');

final newTransaction = Transaction(name: 'Groceries', amount: 55.70, isExpense: true);

// Using an auto-incrementing integer key
await transactionsBox.add(newTransaction); 

// Using a custom string key
await transactionsBox.put('tx-123', newTransaction);

